I haven't yet tried to integrate this into System.DirectoryServices.Protocols, but I don't think it should be too difficult to integrate. I have a proof of concept below.

> 1.  ... take a look in particular to all of the options and settings that are related to SSL/TLS as we would have to be able to control some of those at least to enable SSL.

I took a look at this and found how to set these options. TLS options in libldap are global, which means that you have to pass a `null` connection handle to the `ldap_set_option` function. I used the CA certfile option with success in my PoC below.

> 2- After that, we currently use ldap_simple_bind to perform the binding to the server with credentials, but we should probably need to switch to use the sasl bind instead.

From what I can tell, SASL bind isn't required, but `ldap_bind` and `ldap_simple_bind` (and their synchronous methods) are all deprecated, and `ldap_sasl_bind` methods are preferred, so we might as well do it. You can do a simple bind with the `ldap_sasl_bind` method by using `LDAP_SASL_SIMPLE` (which is just a `null` string) as the mechanism.

<details>
<summary>So the minimal program to connect to a TLS LDAP server in C is:</summary>

```c
#include <lber.h>
#include <ldap.h>
#include <stdio.h>

int main() {
  LDAP *ldp;
  ldap_initialize(&ldp, "ldaps://localhost:1636");
  int version = LDAP_VERSION3;
  ldap_set_option(ldp, LDAP_OPT_PROTOCOL_VERSION, &version);

  // Self-signed cert setting
  // TLS options are global
  ldap_set_option(NULL, LDAP_OPT_X_TLS_CACERTFILE, "/tmp/ca.crt");

  const char *mechanism = LDAP_SASL_SIMPLE;
  const char *dn = "cn=admin,dc=example,dc=org";
  const char *password = "admin";
  struct berval *cred = ber_bvstr(password);
  int bind_result =
      ldap_sasl_bind_s(ldp, dn, mechanism, cred, NULL, NULL, NULL);
  printf("%d: %s\n", bind_result, ldap_err2string(bind_result));
  return bind_result;
}
```

</details>

<details>
<summary>That translates to this (roughly) in C#</summary>

```csharp
using System;
using System.Runtime.InteropServices;
using Microsoft.Win32.SafeHandles;

namespace LdapTest
{
    class Program
    {
        static void Main(string[] args)
        {
            var ldp = new ConnectionHandle("ldaps://localhost:1636");

            IntPtr LDAP_VERSION3 = new IntPtr(3);
            Ldap.ldap_set_option_ptr(ldp, LdapOption.LDAP_OPT_VERSION, ref LDAP_VERSION3);

            // Setting for self-signed certificate
            IntPtr caFilePath = Marshal.StringToHGlobalAuto("/tmp/ca.crt");
            // TLS options are global in OpenLDAP
            Ldap.ldap_set_global_option(LdapOption.LDAP_OPT_X_TLS_CACERTFILE, caFilePath);

            var dn = "cn=admin,dc=example,dc=org";
            berval cred = new berval("admin");
            int bindResult = Ldap.ldap_sasl_bind_s(ldp, dn, Ldap.LDAP_SASL_SIMPLE, cred, IntPtr.Zero, IntPtr.Zero, IntPtr.Zero);
            Console.WriteLine(bindResult == Ldap.LDAP_SUCCESS ? "Connection established successfully" : "Failed to connect");
        }

    }

    internal static class Libraries
    {
        internal const string OpenLdap = "libldap-2.4.so.2";
    }
    internal static class Ldap
    {

        public static IntPtr LDAP_VERSION3 = new IntPtr(3);
        public static string LDAP_SASL_SIMPLE = null;
        public static int LDAP_SUCCESS = 0;

        [DllImport(Libraries.OpenLdap, EntryPoint = "ldap_initialize", CharSet = CharSet.Ansi, SetLastError = true)]
        public static extern int ldap_initialize(out IntPtr ld, string uri);

        [DllImport(Libraries.OpenLdap, EntryPoint = "ldap_set_option", CharSet = CharSet.Ansi)]
        public static extern int ldap_set_option_ptr([In] ConnectionHandle ldapHandle, [In] LdapOption option, ref IntPtr inValue);

        public static int ldap_set_global_option([In] LdapOption option, IntPtr inValue) => ldap_set_option(IntPtr.Zero, option, inValue);


        [DllImport(Libraries.OpenLdap, EntryPoint = "ldap_sasl_bind_s", CharSet = CharSet.Ansi, SetLastError = true)]
        public static extern int ldap_sasl_bind_s([In] ConnectionHandle ld, string dn, string mechanism, berval cred, IntPtr serverctrls, IntPtr clientctrls, IntPtr servercredp);


        [DllImport(Libraries.OpenLdap, EntryPoint = "ldap_set_option", CharSet = CharSet.Ansi, SetLastError = true)]
        public static extern int ldap_set_option([In] IntPtr ld, LdapOption option, IntPtr value);


        [DllImport(Libraries.OpenLdap, EntryPoint = "ldap_unbind_ext_s", CharSet = CharSet.Ansi)]
        public static extern int ldap_unbind_ext_s(IntPtr ld, ref IntPtr serverctrls, ref IntPtr clientctrls);
    }

    // Copied mostly from System.DirectoryServices.Protocols
    internal sealed class ConnectionHandle : SafeHandleZeroOrMinusOneIsInvalid
    {
        internal bool _needDispose;

        // Added this constructor
        public ConnectionHandle(string uri)
            : base(true)
        {
            Ldap.ldap_initialize(out handle, uri);
            _needDispose = true;
        }

        public ConnectionHandle()
            : base(true)
        {
            Ldap.ldap_initialize(out handle, null);
            _needDispose = true;
        }

        internal ConnectionHandle(IntPtr value, bool disposeHandle) : base(true)
        {
            _needDispose = disposeHandle;
            if (value == IntPtr.Zero)
            {
                throw new Exception("Failed to connect to LDAP");
            }
            else
            {
                SetHandle(value);
            }
        }

        protected override bool ReleaseHandle()
        {
            if (_needDispose)
            {
                IntPtr nullPointer = IntPtr.Zero;
                Ldap.ldap_unbind_ext_s(handle, ref nullPointer, ref nullPointer);
            }

            handle = IntPtr.Zero;
            return true;
        }
    }

    internal enum LdapOption
    {
        LDAP_OPT_VERSION = 0x11,
        LDAP_OPT_X_TLS_CACERTFILE	 = 0x6002,
    }

    [StructLayout(LayoutKind.Sequential)]
    internal sealed class berval
    {
        public int bv_len;
        public IntPtr bv_val = IntPtr.Zero;

        public berval() { }
        public berval(string value)
        {
            bv_len = value.Length;
            bv_val = Marshal.StringToHGlobalAuto(value);
        }
    }
}
```
</details>

FYI, I tested using the [osixia/openldap](https://github.com/osixia/docker-openldap) container. In my actual testing, I substituted `localhost` with the container hostname to test actual hostname verification in the LDAP client.

```
podman run -p 1389:389 -p 1636:636 --rm --name ldap -e LDAP_TLS_VERIFY_CLIENT=never osixia/openldap --loglevel debug

# Connect to server to get generated CA cert. An alternative is to specify your own cert and mount into container.
openssl s_client -connect localhost:1636  -servername 99618620fd3b -showcerts < /dev/null
# Copy CA certificate from output and write to /tmp/ca.crt
# wl-paste > /tmp/ca.crt
dotnet run
```
